<form method="post" enctype="multipart/form-data" data-confirm="<?=access_h(match($form){'approve'=>'Approve these exact stock facts? Held items still need actual disposition; verified already-gone items post once.','dispose'=>'Record the actual verified disposition once?','correct_report'=>'Release only the physically verified safe excess? Original history remains and any prior approval is revoked.',default=>'Record this action and retain the original history?'})?>"><?php si_fields($form,$fields);?>
<?php if($form==='correct_report'):?><label>Correct Remaining Quantity *<input type="number" name="qty" min="0" step="0.01" max="<?=si_qty($c['qty'])?>" required value="<?=access_h(si_value('qty',si_qty($c['qty'])))?>"></label><p>Reduce only the mistaken excess. Zero cancels this uncompleted report. No stock movement occurs; a remaining quantity needs fresh approval.</p><div class="si-preview" id="stockissue-release" data-original="<?=$c['qty']?>" data-held="<?=$p['held']?>" data-stock="<?=$p['on_hand']?>" aria-live="polite"></div><?php si_text('Reason','reason',true);si_check('I physically verified the released excess is safe and saleable, and this corrects only a mistaken report.');?>
<?php elseif($form==='dispose'):?><label>Actual Disposition Time (UTC) *<input type="datetime-local" name="actual_at" step="1" required min="<?=access_h(str_replace(' ','T',$c['approval']['created_at']))?>" max="<?=gmdate('Y-m-d\TH:i:s')?>" value="<?=access_h(si_value('actual_at',gmdate('Y-m-d\TH:i:s')))?>"></label><?php si_check($d['kind']==='complimentary'?'I verified the approved items were actually supplied.':($d['kind']==='missing'?'I verified the missing-stock finding and its original count evidence.':'I verified the actual safe disposal / disposition.'));?>
<?php else:si_text($form==='return'?'What Needs Checking?':'Comment','comment',in_array($form,['return','clarify'],true));if($form==='clarify')si_upload();if($form==='approve')si_check('I checked the original report, quantity, evidence, linked count and actual position.');?><?php endif?>
<div class="si-preview"><?php if($d['count_id']):?>Disposition only · Zero additional quantity deduction.<?php elseif($form==='dispose'||$form==='approve'&&$d['position']==='gone'):?>Recorded On Hand <?=si_qty($p['on_hand'])?> → <?=si_qty($p['on_hand']-$c['qty'])?> · Other Holds Retained<?php elseif($form==='approve'):?>Approval only. Recorded quantity stays unchanged until actual disposition.<?php else:?>Original evidence stays retained.<?php endif?></div>
<div class="si-actions"><button type="submit"><?=access_h(match($form){
